window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[19]={"id":"019","numero":19,"titre":"Sécurité sociale, assurance maladie, assurances complémentaires","objectifs":[{"id":"19-1","rang":"A","rubrique":"Définition","titre":"Protection sociale : connaître la définition et les principes de fonctionnement","contenu":"<p>La <strong><span class=\"kw-def\">protection sociale</span></strong> désigne l'<span class=\"kw-def\">ensemble des mécanismes de protection</span> qu'une société accorde à ses membres pour faire face aux <strong><span class=\"kw-def\">risques sociaux</span></strong> de l'existence et à leurs <span class=\"kw-def\">conséquences financières</span>.</p>\n<p>Les <strong><span class=\"kw-def\">risques sociaux</span></strong> sont les situations qui compromettent la sécurité financière de l'individu ou de sa famille, par baisse des ressources ou hausse des dépenses : <span class=\"kw-etio\">vieillesse</span>, <span class=\"kw-etio\">maladie</span>, <span class=\"kw-etio\">chômage</span>, <span class=\"kw-etio\">charges de famille</span>…</p>\n<h4 class=\"kw-def\">4 logiques de protection sociale (coexistantes)</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Assurance sociale obligatoire</span></strong> : prémunir contre une <span class=\"kw-clinique\">perte de revenus</span> (chômage, maladie, vieillesse, AT) ; logique <strong>contributive</strong> (financée par <span class=\"kw-def\">cotisations</span> sur les revenus, réservée aux cotisants et ayants droit) ; repose sur la <strong><span class=\"kw-def\">mutualisation des risques</span></strong> ; l'affiliation obligatoire surmonte la <strong><span class=\"kw-def\">sélection adverse</span></strong> (tarification selon l'âge / les ATCD).</li>\n  <li><strong><span class=\"kw-def\">Assistance sociale</span></strong> : <span class=\"kw-def\">solidarité</span> contre la <span class=\"kw-etio\">pauvreté</span> et l'<span class=\"kw-etio\">exclusion</span> ; garantit un <span class=\"kw-def\">revenu minimum</span> (<strong><span class=\"kw-def\">RSA</span></strong>, <strong><span class=\"kw-def\">AAH</span></strong>) ; sous <strong>conditions de ressources</strong> ; <strong><span class=\"kw-alerte\">non contributive</span></strong> (aucune cotisation préalable).</li>\n  <li><strong><span class=\"kw-def\">Protection universelle</span></strong> : prestations <strong>sans condition de ressources</strong>, identiques pour tous (ex. prestations familiales).</li>\n  <li><strong><span class=\"kw-def\">Prévoyance</span></strong> : <span class=\"kw-def\">individuelle</span> (épargne + assurance privée) ou <span class=\"kw-def\">collective</span> (mutualisation des risques).</li>\n</ul>\n<h4 class=\"kw-def\">Organisation en 4 niveaux</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Sécurité sociale</span></strong> : 4 branches (bientôt 5).</li>\n  <li><strong><span class=\"kw-def\">Régimes complémentaires</span></strong>, obligatoires ou facultatifs : <span class=\"kw-def\">mutuelles</span>, <span class=\"kw-def\">assurances privées</span>, <span class=\"kw-def\">institutions de prévoyance</span> (complètent la SS).</li>\n  <li><strong><span class=\"kw-def\">Régime d'assurance-chômage</span></strong>.</li>\n  <li><strong><span class=\"kw-def\">Aide sociale</span></strong> de l'État et des collectivités (conseils départementaux, communes).</li>\n</ul>\n<div class=\"callout callout-warn\">⚠️ <strong>Pièges ECNi.</strong> Le <strong>chômage</strong> est couvert par <span class=\"kw-def\">France Travail</span>, <strong>institution indépendante</strong> de la Sécurité sociale ; en revanche les <span class=\"kw-def\">allocations familiales</span> sont bien une <strong>branche de la SS</strong>.</div>","frequence":0},{"id":"19-2","rang":"A","rubrique":"Définition","titre":"Connaître la nature des prestations de protection sociale en France","contenu":"<p>La protection sociale agit par deux canaux : l'<span class=\"kw-def\">accès à des services sociaux</span> fournis gratuitement ou à prix réduit (crèches, cantines) et le <strong><span class=\"kw-def\">versement de prestations sociales</span></strong> directement aux individus.</p>\n<h4 class=\"kw-def\">Deux natures de prestations versées</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Prestations en espèces</span></strong> = <span class=\"kw-def\">revenu de remplacement</span> : indemnités journalières, pensions de retraite.</li>\n  <li><strong><span class=\"kw-def\">Prestations en nature</span></strong> : <span class=\"kw-def\">remboursement</span> de dépenses engagées (soins de santé) ou <strong><span class=\"kw-def\">financement direct</span></strong> de services sans avance de frais (médicaments, <strong><span class=\"kw-def\">tiers payant</span></strong>).</li>\n</ul>\n<h4 class=\"kw-def\">6 catégories de prestations = 6 risques</h4>\n<table >\n  <thead><tr><th>Risque</th><th>Part</th><th>Exemples</th></tr></thead>\n  <tbody>\n    <tr><td><strong><span class=\"kw-def\">Vieillesse-survie</span></strong></td><td><strong><span class=\"kw-chiffre\">45 %</span></strong></td><td>Retraites (part la plus importante) ; minimum vieillesse ; pensions de réversion</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Santé</span></strong></td><td><strong><span class=\"kw-chiffre\">35 %</span></strong></td><td>Remboursements de soins (ville et hôpital) ; indemnités journalières ; rentes d'invalidité</td></tr>\n    <tr><td><span class=\"kw-def\">Famille</span></td><td><span class=\"kw-chiffre\">8 %</span></td><td>Allocations familiales ; bourses d'études</td></tr>\n    <tr><td><span class=\"kw-def\">Emploi</span></td><td><span class=\"kw-chiffre\">6 %</span></td><td>Allocations chômage ; formation professionnelle</td></tr>\n    <tr><td><span class=\"kw-def\">Pauvreté-exclusion</span></td><td><span class=\"kw-chiffre\">3 %</span></td><td>RSA</td></tr>\n    <tr><td><span class=\"kw-def\">Logement</span></td><td><span class=\"kw-chiffre\">2 %</span></td><td>APL (aide personnalisée au logement)</td></tr>\n  </tbody>\n</table>\n<div class=\"callout callout-info\">Les deux premiers risques — <strong><span class=\"kw-def\">vieillesse</span></strong> et <strong><span class=\"kw-def\">santé</span></strong> — concentrent à eux seuls <strong><span class=\"kw-chiffre\">≈ 80 %</span></strong> des prestations sociales versées.</div>","frequence":0},{"id":"19-3","rang":"B","rubrique":"Définition","titre":"Connaître la poids des prestations vieillesse et santé","contenu":"<p>Parmi les 6 risques sociaux, <strong>deux postes dominent</strong> très largement les dépenses de protection sociale : la <strong><span class=\"kw-def\">vieillesse</span></strong> et la <strong><span class=\"kw-def\">santé</span></strong>.</p>\n<ul>\n  <li><strong><span class=\"kw-def\">Vieillesse-survie</span></strong> : <strong><span class=\"kw-chiffre\">45 %</span></strong> des prestations = <strong>poste nº 1</strong> → <span class=\"kw-def\">retraites</span> (part la plus importante), <span class=\"kw-def\">minimum vieillesse</span>, <span class=\"kw-def\">pensions de réversion</span>.</li>\n  <li><strong><span class=\"kw-def\">Santé</span></strong> : <strong><span class=\"kw-chiffre\">35 %</span></strong> des prestations = poste nº 2 → <span class=\"kw-def\">soins</span> de ville et hospitaliers, <span class=\"kw-clinique\">indemnités journalières</span>, <span class=\"kw-clinique\">rentes d'invalidité</span>.</li>\n</ul>\n<p>À eux deux, vieillesse et santé concentrent environ <strong><span class=\"kw-chiffre\">80 %</span></strong> de l'ensemble des prestations sociales, loin devant <span class=\"kw-def\">famille</span> (<span class=\"kw-chiffre\">8 %</span>) et <span class=\"kw-def\">emploi</span> (<span class=\"kw-chiffre\">6 %</span>).</p>\n<h4 class=\"kw-def\">Évolution : un poids croissant dans le PIB</h4>\n<ul>\n  <li>Le poids des prestations sociales dans le <strong><span class=\"kw-def\">PIB</span></strong> est passé de <span class=\"kw-chiffre\">24 % (1981)</span> à plus de <strong><span class=\"kw-chiffre\">31 % (2018)</span></strong> : elles progressent <strong>plus vite que la richesse nationale</strong>.</li>\n  <li>La <strong>France</strong> consacre <strong>le plus de ressources</strong> à la protection sociale en <span class=\"kw-def\">Europe</span> (devant le <span class=\"kw-chiffre\">Danemark 30,8 %</span> et la <span class=\"kw-chiffre\">Finlande 30,1 %</span>).</li>\n  <li>La progression du poste vieillesse-survie est tirée par le <strong><span class=\"kw-etio\">vieillissement démographique</span></strong> et l'arrivée à la retraite du <span class=\"kw-etio\">baby-boom</span> → réformes successives (recul de l'âge de départ à la retraite).</li>\n</ul>","frequence":0},{"id":"19-4","rang":"B","rubrique":"Définition","titre":"Connaître le financement de la protection sociale : cotisations sociales, ressources fiscales, contributions publiques de l’Etat","contenu":"<p>Les ressources de la protection sociale se répartissent en <strong>quatre grandes catégories</strong>, dont le poids relatif a fortement évolué : glissement des <span class=\"kw-def\">cotisations</span> vers la <span class=\"kw-def\">fiscalité</span>.</p>\n<h4 class=\"kw-def\">Cotisations sociales</h4>\n<ul>\n  <li><span class=\"kw-def\">Versements obligatoires</span> des salariés, non-salariés et employeurs ouvrant des <strong>droits à prestations</strong> : assurance <span class=\"kw-def\">maladie-maternité-invalidité-décès</span>, <span class=\"kw-def\">vieillesse</span>, <span class=\"kw-def\">chômage</span>, <span class=\"kw-def\">allocations familiales</span>.</li>\n  <li><strong>1<sup>re</sup> source</strong> de financement historiquement, mais <strong>en diminution</strong> : <span class=\"kw-chiffre\">77 % (1959)</span> → <span class=\"kw-chiffre\">59 % (2018)</span>.</li>\n  <li>S'y ajoute la <strong><span class=\"kw-def\">contribution solidarité autonomie</span></strong> (CSA, journée de solidarité), due par les employeurs.</li>\n</ul>\n<h4 class=\"kw-def\">Ressources fiscales (impôts et taxes affectés, ITAF)</h4>\n<ul>\n  <li>Part <strong>croissante</strong> des ressources ; la plus importante provient des impôts sur le <strong>revenu et le patrimoine</strong>.</li>\n  <li><strong><span class=\"kw-def\">CSG</span></strong> (contribution sociale généralisée), créée en <span class=\"kw-chiffre\">1991</span> : <span class=\"kw-chiffre\">0 %</span> au départ → <strong><span class=\"kw-chiffre\">16 % (2018)</span></strong> ; s'applique à <strong>tous les revenus</strong>, pas seulement aux salaires.</li>\n  <li><strong><span class=\"kw-def\">CRDS</span></strong> : contribution au remboursement de la dette sociale.</li>\n  <li>Autres : taxes sur les produits (<span class=\"kw-etio\">alcools</span>, <span class=\"kw-etio\">tabac</span>, assurances auto), impôts sur les salaires.</li>\n</ul>\n<h4 class=\"kw-def\">Contributions publiques de l'État</h4>\n<ul>\n  <li>Financent les dépenses de <strong><span class=\"kw-def\">solidarité</span></strong> : <span class=\"kw-def\">RSA</span>, <span class=\"kw-def\">fonds de solidarité vieillesse</span>.</li>\n  <li>Financent une partie des <span class=\"kw-def\">exonérations de cotisations</span> employeurs.</li>\n  <li><span class=\"kw-def\">Subventionnent</span> certains régimes déficitaires (actifs cotisants &lt; retraités).</li>\n</ul>\n<div class=\"callout callout-info\">Logique de l'évolution : <strong>alléger le coût du travail</strong> en ne faisant plus reposer le financement sur les seuls revenus salariaux → montée de la <strong><span class=\"kw-def\">CSG</span></strong>. Malgré tout, les <strong><span class=\"kw-alerte\">dépenses restent supérieures aux recettes</span></strong> (déficit en réduction depuis 2011).</div>","frequence":0},{"id":"19-5","rang":"A","rubrique":"Définition","titre":"Connaître le régime général de la sécurité sociale","contenu":"<p>Le <strong><span class=\"kw-def\">régime général</span></strong> est le principal régime de la Sécurité sociale : il couvre <strong><span class=\"kw-chiffre\">88 %</span></strong> de la population (salariés, étudiants, simples résidents et, depuis <span class=\"kw-chiffre\">2018</span>, les <span class=\"kw-def\">indépendants</span> — ex-RSI).</p>\n<h4 class=\"kw-def\">4 branches autonomes (+ une 5ᵉ en construction)</h4>\n<p>Chaque branche doit assurer son propre <strong><span class=\"kw-def\">équilibre financier</span></strong> recettes / dépenses et est pilotée par une <strong><span class=\"kw-def\">Caisse nationale</span></strong> coordonnant un réseau de caisses territoriales (organismes de droit privé, mission de service public, sous tutelle de l'État).</p>\n<table >\n  <thead><tr><th>Branche</th><th>Caisse</th><th>Périmètre</th></tr></thead>\n  <tbody>\n    <tr><td><strong><span class=\"kw-def\">Maladie</span></strong></td><td><strong><span class=\"kw-def\">CNAM</span></strong></td><td>Maladie, maternité, invalidité, décès ; intègre les <strong><span class=\"kw-def\">AT/MP</span></strong> (accidents du travail-maladies professionnelles)</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Famille</span></strong></td><td><strong><span class=\"kw-def\">CAF</span></strong></td><td><span class=\"kw-def\">Allocations familiales</span> ; logement ; <span class=\"kw-def\">RSA</span></td></tr>\n    <tr><td><strong><span class=\"kw-def\">Vieillesse</span></strong></td><td><strong><span class=\"kw-def\">CNAV</span></strong> (Assurance Retraite)</td><td><span class=\"kw-def\">Retraites</span> des salariés du privé</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Recouvrement</span></strong></td><td><strong><span class=\"kw-def\">URSSAF</span></strong></td><td>Collecte des <span class=\"kw-def\">cotisations sociales</span> (employeurs, indépendants)</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Autonomie</span></strong> (5ᵉ)</td><td><strong><span class=\"kw-def\">CNSA</span></strong></td><td>Branche en cours de constitution (perte d'autonomie)</td></tr>\n  </tbody>\n</table>\n<div class=\"callout callout-warn\">⚠️ <strong>Distracteur ECNi.</strong> Le <strong><span class=\"kw-alerte\">chômage</span></strong> ne fait <strong>pas</strong> partie du régime général ni de la Sécurité sociale : il est géré de façon <strong>indépendante</strong> (France Travail). La <strong>branche Recouvrement</strong> (URSSAF), elle, est bien une branche à part entière.</div>","frequence":0},{"id":"19-6","rang":"B","rubrique":"Définition","titre":"Connaître la loi de financement de la Sécurité Sociale (LFSS)","contenu":"<p>La <strong><span class=\"kw-def\">loi de financement de la Sécurité sociale</span></strong> (<strong><span class=\"kw-def\">LFSS</span></strong>) détermine les conditions de l'<span class=\"kw-def\">équilibre financier</span> de la <span class=\"kw-def\">Sécurité sociale</span> : elle fixe ses <span class=\"kw-def\">objectifs de dépenses</span> à partir des <span class=\"kw-def\">prévisions de recettes</span>.</p>\n<ul>\n  <li><strong><span class=\"kw-def\">Votée chaque année par le Parlement</span></strong>, en même temps que la <strong><span class=\"kw-def\">loi de finances</span></strong> (LF) qui fixe le <span class=\"kw-def\">budget de l'État</span>.</li>\n  <li>Peut être modifiée en cours d'année par une <strong><span class=\"kw-def\">LFSS rectificative</span></strong>.</li>\n  <li>C'est elle qui fixe chaque année l'<strong><span class=\"kw-def\">ONDAM</span></strong>.</li>\n</ul>\n<div class=\"callout callout-warn\">⚠️ <strong>Loi de FINANCEMENT, et non de finances</strong> → <strong><span class=\"kw-alerte\">portée budgétaire limitée</span></strong> :\n<ul>\n  <li>Les <strong><span class=\"kw-def\">recettes</span></strong> <strong>ne peuvent pas être fixées</strong> par le Parlement : la LFSS ne fait que les <strong>prévoir</strong>.</li>\n  <li>Les <strong><span class=\"kw-def\">objectifs de dépenses</span></strong> sont votés mais <strong><span class=\"kw-alerte\">évaluent les dépenses sans les limiter</span></strong>.</li>\n  <li>Le <strong><span class=\"kw-def\">contrôle parlementaire</span></strong> reste donc <strong>limité</strong>.</li>\n</ul>\n</div>","frequence":0},{"id":"19-7","rang":"B","rubrique":"Définition","titre":"Connaître la définition de l’Objectif national des dépenses d’Assurance maladie (ONDAM)","contenu":"<p>L'<strong><span class=\"kw-def\">Objectif national des dépenses d'Assurance maladie</span></strong> (<strong><span class=\"kw-def\">ONDAM</span></strong>) est le <strong><span class=\"kw-def\">montant prévisionnel</span> à ne pas dépasser</strong> pour les <span class=\"kw-def\">soins de ville</span> et l'<span class=\"kw-def\">hospitalisation</span> (établissements publics, privés et médico-sociaux).</p>\n<ul>\n  <li><strong>Fixé chaque année par la <span class=\"kw-def\">LFSS</span></strong>.</li>\n  <li>Montant <strong>prévisionnel</strong>, établi chaque année pour les dépenses de l'<span class=\"kw-def\">Assurance maladie</span> en France.</li>\n</ul>\n<h4 class=\"kw-def\">6 sous-catégories de l'ONDAM</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Soins de ville</span></strong>.</li>\n  <li>Établissements <strong><span class=\"kw-def\">tarifés à l'activité</span></strong> (<span class=\"kw-def\">T2A</span>).</li>\n  <li>Autres dépenses des <span class=\"kw-def\">établissements de santé</span>.</li>\n  <li>Établissements et services pour <span class=\"kw-def\">personnes âgées</span>.</li>\n  <li>Établissements et services pour <span class=\"kw-def\">personnes handicapées</span>.</li>\n  <li>Autres modes de <span class=\"kw-def\">prise en charge</span>.</li>\n</ul>\n<div class=\"callout callout-warn\">⚠️ <strong>Piège.</strong> L'ONDAM <strong>n'inclut PAS</strong> les frais <strong>non pris en charge</strong> par l'<span class=\"kw-def\">Assurance maladie</span> (ex. <strong><span class=\"kw-alerte\">ticket modérateur</span></strong>).</div>","frequence":0},{"id":"19-8","rang":"A","rubrique":"Définition","titre":"Connaître les différents régimes de sécurité sociale","contenu":"<p>La Sécurité sociale regroupe les assurés en <strong>différents régimes</strong>, selon leur <strong>activité professionnelle</strong>.</p>\n<table >\n  <thead><tr><th>Régime</th><th>Population</th><th>Qui ?</th></tr></thead>\n  <tbody>\n    <tr><td><strong><span class=\"kw-def\">Régime général</span></strong></td><td><strong><span class=\"kw-chiffre\">88 %</span></strong></td><td>Salariés, étudiants, simples résidents ; depuis <span class=\"kw-chiffre\">2018</span> les <strong><span class=\"kw-def\">indépendants</span></strong> (ex-RSI)</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Régime agricole</span></strong> (<strong><span class=\"kw-def\">MSA</span></strong>)</td><td><strong><span class=\"kw-chiffre\">5 %</span></strong></td><td>Exploitants et salariés agricoles</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Régimes spéciaux</span></strong></td><td>—</td><td><span class=\"kw-chiffre\">130</span> régimes antérieurs à 1945 : fonction publique, SNCF, RATP, EDF-GDF, mines…</td></tr>\n  </tbody>\n</table>\n<ul>\n  <li>Les <strong><span class=\"kw-def\">régimes spéciaux</span></strong> ont <strong>refusé de s'intégrer</strong> au régime général en <span class=\"kw-chiffre\">1945</span> ; seuls <span class=\"kw-chiffre\">11</span> recensent <strong><span class=\"kw-chiffre\">&gt; 20 000 cotisants</span></strong>.</li>\n  <li>Depuis <span class=\"kw-chiffre\">2018</span>, la protection sociale des <strong><span class=\"kw-def\">indépendants</span></strong> (ancien <strong><span class=\"kw-def\">RSI</span></strong>) est confiée au <span class=\"kw-def\">régime général</span>.</li>\n</ul>\n<div class=\"callout callout-info\">Repère mémo : le <strong>régime général couvre ~9 Français sur 10</strong> (<span class=\"kw-chiffre\">88 %</span>), le régime agricole <span class=\"kw-chiffre\">5 %</span>, le reste se partageant entre les régimes spéciaux.</div>","frequence":0},{"id":"19-9","rang":"A","rubrique":"Définition","titre":"Connaître les missions de l’assurance maladie du régime général de la sécurité sociale","contenu":"<p>L'<strong><span class=\"kw-def\">Assurance maladie</span></strong> (<strong><span class=\"kw-def\">CNAM</span></strong>) gère, au sein du régime général, les risques <span class=\"kw-def\">maladie</span>, <span class=\"kw-def\">maternité</span>, <span class=\"kw-def\">invalidité-décès</span> et <strong><span class=\"kw-def\">AT/MP</span></strong>.</p>\n<h4 class=\"kw-def\">Missions principales</h4>\n<ul>\n  <li><strong>Mission centrale</strong> : <strong><span class=\"kw-def\">prise en charge des soins</span></strong> dispensés aux assurés sociaux.</li>\n  <li><span class=\"kw-def\">Amélioration de la santé</span> de la population, <strong><span class=\"kw-def\">efficience</span></strong> du système de soins, <strong><span class=\"kw-def\">maîtrise des dépenses</span></strong> de santé.</li>\n</ul>\n<h4 class=\"kw-def\">Leviers d'action</h4>\n<ul>\n  <li><strong>Périmètre des actes remboursables</strong> : défini avec la <span class=\"kw-def\">MSA</span>, sur avis de la <strong><span class=\"kw-def\">HAS</span></strong>.</li>\n  <li><strong><span class=\"kw-def\">Négociations conventionnelles</span></strong> : régissent les relations avec les professionnels de santé libéraux (tarifs, pratiques).</li>\n  <li><strong><span class=\"kw-def\">Tarification</span></strong> : codage des actes par la <strong><span class=\"kw-def\">CCAM</span></strong> et la <span class=\"kw-def\">NGAP</span>, <strong><span class=\"kw-def\">T2A</span></strong> pour les établissements ; l'<strong><span class=\"kw-def\">UNCAM</span></strong> (régime général + MSA) fixe le taux de PEC et le champ des prestations remboursables.</li>\n  <li><strong><span class=\"kw-def\">Gestion du risque</span></strong> : maîtrise <strong>médicalisée</strong> des dépenses (efficience qualité / coût) ; participation au <strong><span class=\"kw-def\">CEPS</span></strong>, qui fixe le prix des médicaments.</li>\n  <li><strong>Planification de l'offre de soins</strong> avec les <strong><span class=\"kw-def\">ARS</span></strong>.</li>\n  <li><strong>Prévention et information</strong> des assurés : <span class=\"kw-def\">tabac</span>, <span class=\"kw-def\">vaccination</span>, <span class=\"kw-def\">dépistage organisé des cancers</span> ; lutte contre la fraude (datamining, big data).</li>\n</ul>\n<h4 class=\"kw-def\">Contrôle médical</h4>\n<p>Le <strong><span class=\"kw-def\">service du contrôle médical</span></strong> (<span class=\"kw-def\">médecins-conseils</span>) vérifie la <strong>pertinence des soins</strong> et peut déclencher des <strong><span class=\"kw-alerte\">sanctions</span></strong> contre les professionnels et assurés <strong>auteurs d'abus ou de fraudes</strong>.</p>\n<h4 class=\"kw-def\">Ouverture des droits : la PUMa</h4>\n<ul>\n  <li>La <strong><span class=\"kw-def\">Protection universelle maladie</span></strong> (<strong><span class=\"kw-def\">PUMa</span></strong>) a remplacé la <strong><span class=\"kw-def\">CMU</span></strong> de base.</li>\n  <li>Elle couvre les frais de santé de toute personne qui <strong>travaille OU réside</strong> en France de façon <strong>stable et régulière</strong> — <strong>sans condition de ressources</strong>.</li>\n  <li>Plus besoin d'être <strong>ayant droit</strong> : <strong>seuls les mineurs (&lt;<span class=\"kw-chiffre\"> 18 ans</span>)</strong> conservent ce statut.</li>\n  <li>Pour les personnes en situation irrégulière : <strong><span class=\"kw-def\">Aide médicale de l'État</span></strong> (<strong><span class=\"kw-def\">AME</span></strong>).</li>\n</ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 59 — Sujet en situation de précarité</em></p>","frequence":0},{"id":"19-10","rang":"A","rubrique":"Définition","titre":"Connaître la définition du ticket modérateur, du forfait hospitalier, de la participation forfaitaire, de la franchise médicale, du tiers payant","contenu":"<p>Quatre dispositifs laissent une <strong>part des frais à la charge du patient</strong> (responsabilisation financière) ; le <strong><span class=\"kw-def\">tiers payant</span></strong>, à l'inverse, le <strong>dispense de l'avance des frais</strong>.</p>\n<h4 class=\"kw-def\">Ticket modérateur (TM)</h4>\n<ul>\n  <li><strong>Définition</strong> : <strong><span class=\"kw-def\">part des frais qui reste à la charge de l'assuré</span></strong> après remboursement par l'Assurance maladie.</li>\n  <li><strong>Objectif</strong> : <strong>responsabiliser financièrement</strong> le patient et réguler la consommation de soins.</li>\n  <li>Peut être <strong>pris en charge</strong> par une <span class=\"kw-def\">mutuelle</span> / assurance complémentaire.</li>\n</ul>\n<h4 class=\"kw-def\">Forfait hospitalier et participations forfaitaires</h4>\n<table >\n  <thead><tr><th>Dispositif</th><th>Montant</th><th>Quand ?</th><th>Plafond</th></tr></thead>\n  <tbody>\n    <tr><td><strong><span class=\"kw-def\">Forfait journalier hospitalier</span></strong></td><td><strong><span class=\"kw-chiffre\">20 €/jour</span></strong></td><td>Toute <strong>hospitalisation</strong> (frais d'hébergement et d'entretien)</td><td>—</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Participation forfaitaire</span></strong></td><td><strong><span class=\"kw-chiffre\">2 €</span></strong></td><td>Chaque <span class=\"kw-def\">consultation</span>, <span class=\"kw-bio\">analyse biologique</span> ou <span class=\"kw-imagerie\">acte de radiologie</span></td><td><strong><span class=\"kw-chiffre\">50 €/an</span></strong></td></tr>\n    <tr><td><strong><span class=\"kw-def\">Franchise médicale</span></strong></td><td><strong><span class=\"kw-chiffre\">1 €</span></strong>/boîte de <span class=\"kw-ttt\">médicament</span> ou acte paramédical ; <strong><span class=\"kw-chiffre\">4 €</span></strong>/transport</td><td>Déduite des remboursements</td><td><strong><span class=\"kw-chiffre\">50 €/an</span></strong> (≤ <span class=\"kw-chiffre\">4 €/jour</span> paramédical, ≤ <span class=\"kw-chiffre\">8 €/jour</span> transport)</td></tr>\n  </tbody>\n</table>\n<div class=\"callout callout-warn\">⚠️ <strong>Forfait hospitalier</strong> : <strong><span class=\"kw-alerte\">non pris en charge par l'Assurance maladie</span></strong>. <strong>Participation forfaitaire et franchise</strong> : <strong><span class=\"kw-alerte\">ne peuvent PAS être prises en charge par une complémentaire</span></strong> (mutuelle).</div>\n<h4 class=\"kw-def\">Dispensés de participation forfaitaire et de franchise</h4>\n<ul>\n  <li><strong>Mineurs &lt;<span class=\"kw-chiffre\"> 18 ans</span></strong>.</li>\n  <li>Bénéficiaires de la <strong><span class=\"kw-def\">Complémentaire santé solidaire</span></strong> (CSS) ou de l'<strong><span class=\"kw-def\">AME</span></strong>.</li>\n  <li><strong>Femmes enceintes</strong> à partir du <strong><span class=\"kw-chiffre\">6ᵉ mois</span></strong> de grossesse.</li>\n</ul>\n<h4 class=\"kw-def\">Tiers payant</h4>\n<ul>\n  <li><strong>Principe</strong> : <strong><span class=\"kw-def\">dispense de l'avance des frais</span></strong> pris en charge par l'AM ; le patient ne règle que le <strong><span class=\"kw-def\">ticket modérateur</span></strong>, l'AM payant directement les soignants.</li>\n  <li><strong>Bénéficiaires</strong> : <strong><span class=\"kw-def\">AT/MP</span></strong>, <strong><span class=\"kw-def\">AME</span></strong>, et tout assuré disposant d'une couverture complémentaire (<span class=\"kw-def\">mutuelle</span>, <span class=\"kw-def\">CSS</span>…) — sur présentation de la carte Vitale et de l'attestation.</li>\n</ul>","frequence":0},{"id":"19-11","rang":"A","rubrique":"Définition","titre":"Connaître le parcours de soins coordonnés","contenu":"<p>Le <strong><span class=\"kw-def\">parcours de soins coordonnés</span></strong> organise la prise en charge autour d'un <strong><span class=\"kw-def\">médecin traitant</span></strong> (MT), pivot de l'orientation et du suivi.</p>\n<h4 class=\"kw-def\">Rôle du médecin traitant</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Premier recours</span></strong> aux soins et <strong><span class=\"kw-def\">coordination</span></strong> du suivi médical.</li>\n  <li><strong>Oriente</strong> vers le spécialiste adapté — <strong>avec l'accord du patient</strong> — qui garantit alors des <strong><span class=\"kw-def\">délais d'accès</span></strong> et un retour d'information.</li>\n  <li>Gère le <span class=\"kw-def\">dossier médical</span>, établit le <strong><span class=\"kw-def\">protocole de soins ALD</span></strong>, assure la <span class=\"kw-def\">prévention</span> personnalisée.</li>\n</ul>\n<h4 class=\"kw-def\">Choix du médecin traitant</h4>\n<ul>\n  <li>Tout patient <strong><span class=\"kw-chiffre\">&gt; 16 ans</span></strong> déclare son MT à la <span class=\"kw-def\">CPAM</span>, <strong>avec l'accord</strong> de ce dernier ; choix <strong>modifiable à tout moment</strong>.</li>\n  <li>Le MT peut être <strong><span class=\"kw-def\">généraliste</span></strong> ou <strong><span class=\"kw-def\">spécialiste</span></strong>, <strong>libéral, hospitalier ou salarié</strong> d'un centre de santé.</li>\n</ul>\n<h4 class=\"kw-def\">Accès direct autorisé (hors parcours)</h4>\n<ul>\n  <li><strong><span class=\"kw-alerte\">Urgences</span></strong>, SAMU, SOS médecins ; consultation hors lieu de résidence ; médecin remplaçant.</li>\n  <li>Accès direct à certaines spécialités : <span class=\"kw-def\">gynécologue</span>, <span class=\"kw-def\">ophtalmologue</span>, <span class=\"kw-def\">stomatologue</span>, <span class=\"kw-def\">psychiatre</span> (remboursé chez les <span class=\"kw-chiffre\">16-25 ans</span> sans adressage).</li>\n</ul>\n<div class=\"callout callout-warn\">⚠️ <strong>Hors parcours = pénalités</strong> (uniquement chez les <strong><span class=\"kw-chiffre\">&gt; 16 ans</span></strong>) :\n<ul>\n  <li>Remboursement abaissé à <strong><span class=\"kw-chiffre\">30 %</span></strong> au lieu de <strong><span class=\"kw-chiffre\">70 %</span></strong>.</li>\n  <li><strong><span class=\"kw-def\">Dépassements d'honoraires</span></strong> autorisés pour les patients non adressés.</li>\n</ul>\n</div>\n<p>Le patient garde la <strong>liberté</strong> de ne pas avoir de MT ; l'enfant <strong>&lt;<span class=\"kw-chiffre\"> 16 ans</span></strong> n'est <strong>pas pénalisé</strong> en l'absence de déclaration.</p>","frequence":0},{"id":"19-12","rang":"A","rubrique":"Définition","titre":"Connaître le protocole de soins affection de longue durée (ALD) avec exonération du ticket modérateur","contenu":"<p>En cas d'<strong><span class=\"kw-def\">affection de longue durée</span></strong> (<strong><span class=\"kw-def\">ALD</span></strong>) comportant un <strong>traitement prolongé et coûteux</strong>, l'assuré est <strong><span class=\"kw-def\">exonéré du ticket modérateur</span></strong> : les soins <strong>en rapport avec l'ALD</strong> sont pris en charge à <strong><span class=\"kw-chiffre\">100 %</span></strong>.</p>\n<h4 class=\"kw-def\">Trois portes d'entrée</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">ALD exonérante (liste)</span></strong> : une des <strong><span class=\"kw-chiffre\">30 affections</span></strong> de la liste (ALD 30) — ex. <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">tumeur maligne</span>, <span class=\"kw-etio\">AVC invalidant</span>, <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">sclérose en plaques</span>, <span class=\"kw-etio\">insuffisance cardiaque grave</span>, affections psychiatriques de longue durée…</li>\n  <li><strong><span class=\"kw-def\">31ᵉ maladie</span></strong> (hors liste) : forme <strong><span class=\"kw-alerte\">grave ou invalidante</span></strong> non listée, <strong>traitement prolongé &gt; <span class=\"kw-chiffre\">6 mois</span></strong> et thérapeutique <strong>coûteuse</strong>.</li>\n  <li><strong><span class=\"kw-def\">32ᵉ maladie</span></strong> : <strong><span class=\"kw-def\">polypathologie invalidante</span></strong> nécessitant des <strong>soins continus &gt; <span class=\"kw-chiffre\">6 mois</span></strong>.</li>\n</ul>\n<h4 class=\"kw-def\">Le protocole de soins</h4>\n<ul>\n  <li><strong>Établi par le <span class=\"kw-def\">médecin traitant</span></strong>, en concertation avec les spécialistes, <strong>conforme aux recommandations de la <span class=\"kw-def\">HAS</span></strong>.</li>\n  <li>Reçoit l'avis du <strong><span class=\"kw-def\">médecin-conseil</span></strong> de l'Assurance maladie.</li>\n  <li>Un exemplaire remis au <strong>patient</strong>, qui le <strong>signe</strong> (libre d'accepter ou non que le diagnostic y figure) ; il a un <strong>accès direct</strong> aux spécialistes du protocole.</li>\n</ul>\n<div class=\"callout callout-info\"><strong>Ordonnance bizone</strong> : sépare les prescriptions <strong>en rapport avec l'ALD</strong> (<strong>exonérées</strong>,<span class=\"kw-chiffre\"> 100 %</span>) de celles <strong>sans rapport</strong> avec l'ALD (<strong><span class=\"kw-def\">ticket modérateur</span> appliqué</strong>).</div>\n<h4 class=\"kw-def\">Contrepartie pour le patient</h4>\n<ul>\n  <li>Présenter son <strong>volet du protocole</strong> à chaque professionnel consulté (sauf urgence).</li>\n  <li>Se <strong>conformer au projet thérapeutique</strong> du médecin traitant.</li>\n  <li>Se présenter aux <strong>contrôles</strong> de l'Assurance maladie.</li>\n</ul>\n<div class=\"callout callout-warn\">⚠️ <strong>Distracteurs ECNi (NON ALD).</strong> Ne figurent <strong>pas</strong> sur la liste : <strong><span class=\"kw-alerte\">maladie cœliaque</span></strong> et <strong><span class=\"kw-alerte\">pemphigoïde bulleuse</span></strong>.</div>","frequence":0},{"id":"19-13","rang":"B","rubrique":"Définition","titre":"Connaître les prestations en espèces et en nature de l’assurance maladie","contenu":"<p>L'Assurance maladie verse deux types de prestations, qui se distinguent par leur <strong>forme</strong> et leurs <strong>bénéficiaires</strong>.</p>\n<table >\n  <thead><tr><th></th><th>Prestations en espèces</th><th>Prestations en nature</th></tr></thead>\n  <tbody>\n    <tr><td><strong>Forme</strong></td><td><strong><span class=\"kw-def\">Revenu de remplacement</span></strong> (compense la perte de salaire)</td><td><strong><span class=\"kw-def\">Remboursement</span></strong> des frais ou <strong><span class=\"kw-def\">prise en charge directe</span></strong> (tiers payant)</td></tr>\n    <tr><td><strong>Bénéficiaires</strong></td><td><strong><span class=\"kw-alerte\">Assuré social uniquement</span></strong> (pas les ayants droit)</td><td>Assuré social <strong>ET ses ayants droit</strong></td></tr>\n    <tr><td><strong>Condition</strong></td><td><strong>Durée minimale</strong> de travail salarié</td><td>Sur <strong>prescription</strong> médicale</td></tr>\n  </tbody>\n</table>\n<h4 class=\"kw-def\">Prestations en espèces : 4 situations</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Indemnités journalières</span></strong> (incapacité temporaire) : versées dès le <strong><span class=\"kw-chiffre\">4ᵉ jour</span></strong> (délai de carence), à <strong><span class=\"kw-chiffre\">50 %</span></strong> du salaire (plafonné) ; <strong>maximum <span class=\"kw-chiffre\">360 IJ</span></strong> sur <span class=\"kw-chiffre\">3 ans</span>.</li>\n  <li><strong><span class=\"kw-def\">Congé maternité</span></strong> : <strong><span class=\"kw-chiffre\">16 semaines</span></strong> indemnisées (<span class=\"kw-chiffre\">6 avant</span> + <span class=\"kw-chiffre\">10 après</span> l'accouchement).</li>\n  <li><strong><span class=\"kw-def\">Pension d'invalidité</span></strong> : altération <strong>définitive</strong> de la capacité de travail d'<strong><span class=\"kw-chiffre\">≥ 2/3</span></strong>, d'origine <strong><span class=\"kw-alerte\">non professionnelle</span></strong> ; versée jusqu'à <strong><span class=\"kw-chiffre\">62 ans</span></strong>.</li>\n  <li><strong><span class=\"kw-def\">Capital décès</span></strong> : versé aux ayants droit si l'assuré était en activité.</li>\n</ul>\n<div class=\"callout callout-warn\">⚠️ <strong>AT/MP = pas de délai de carence</strong> sur les IJ (versées dès le 1<sup>er</sup> jour) et montant majoré : <strong><span class=\"kw-chiffre\">60 %</span></strong> du salaire les 28 premiers jours, puis <strong><span class=\"kw-chiffre\">80 %</span></strong> dès le <strong><span class=\"kw-chiffre\">29ᵉ jour</span></strong>.</div>\n<h4 class=\"kw-def\">Pension d'invalidité : 3 catégories</h4>\n<ul>\n  <li><strong>Catégorie 1</strong> (peut encore travailler) : <strong><span class=\"kw-chiffre\">30 %</span></strong> du salaire antérieur.</li>\n  <li><strong>Catégorie 2</strong> (ne peut plus travailler) : <strong><span class=\"kw-chiffre\">50 %</span></strong>.</li>\n  <li><strong>Catégorie 3</strong> (besoin d'une tierce personne) : <strong><span class=\"kw-chiffre\">50 %</span></strong> + <strong>majoration pour tierce personne</strong>.</li>\n</ul>\n<h4 class=\"kw-def\">Prestations en nature : frais couverts</h4>\n<ul>\n  <li>Frais de <span class=\"kw-def\">médecine</span> générale et spécialisée, <span class=\"kw-def\">soins dentaires</span> et prothèses.</li>\n  <li>Frais <span class=\"kw-def\">pharmaceutiques</span>, d'<span class=\"kw-def\">appareillage</span>, d'<span class=\"kw-bio\">analyses biologiques</span>.</li>\n  <li>Frais d'<span class=\"kw-def\">hospitalisation</span>, de réadaptation, de <span class=\"kw-def\">transports sanitaires</span>.</li>\n  <li>Frais de <span class=\"kw-def\">vaccinations</span> et d'<span class=\"kw-def\">examens de dépistage</span> (programmes de santé publique).</li>\n</ul>","frequence":0}],"astuces":[],"strategie":{},"liensGlobaux":[{"href":"https://www.complementaire-sante-solidaire.gouv.fr/presentation-du-droit","label":"Complémentaire santé solidaire — présentation du droit"},{"href":"https://www.ameli.fr/assure/droits-demarches/difficultes-acces-droits-soins/complementaire-sante/complementaire-sante-solidaire","label":"Ameli — Complémentaire santé solidaire"}],"cards":[{"i":"23cb88e8daa1","n":19,"o":"19-1","u":"Définition","t":"Protection sociale : connaître la définition et les principes de fonctionnement","q":"Comment est organisée la protection sociale en France sur le plan institutionnel ?","a":"<p>La protection sociale est organisée en 4 niveaux principaux :</p><ul><li>La <strong>Sécurité sociale</strong> (4 branches et bientôt 5).</li><li>Les <strong>régimes complémentaires</strong>, obligatoires ou facultatifs (mutuelles, assurances privées, institutions de prévoyance).</li><li>Le <strong>régime d'assurance-chômage</strong> (géré par France Travail).</li><li>L'<strong>aide sociale</strong> de l'État et des collectivités (conseils départementaux, communes).</li></ul>"},{"i":"2b1ad4844af7","n":19,"o":"19-1","u":"Définition","t":"Protection sociale : connaître la définition et les principes de fonctionnement","q":"Quelle différence existe-t-il entre la couverture du chômage et celle des allocations familiales concernant leur rattachement à la Sécurité sociale ?","a":"<p>Le <strong>chômage est couvert par France Travail</strong> (anciennement Pôle emploi), une institution indépendante de la Sécurité sociale. En revanche, les <strong>allocations familiales sont bien une branche de la Sécurité sociale</strong>.</p>"},{"i":"a19ba972b282","n":19,"o":"19-1","u":"Définition","t":"Protection sociale : connaître la définition et les principes de fonctionnement","q":"Quelles sont les 4 logiques de protection sociale coexistantes en France ?","a":"<p>Les 4 logiques de protection sociale sont :</p><ul><li>L'<strong>assurance sociale obligatoire</strong> : prémunit contre une perte de revenus (maladie, vieillesse, chômage, AT), financée par les cotisations (logique contributive).</li><li>L'<strong>assistance sociale</strong> : lutte contre la pauvreté et l'exclusion, garantit un revenu minimum (RSA, AAH), sous conditions de ressources (non contributive).</li><li>La <strong>protection universelle</strong> : prestations sans condition de ressources, identiques pour tous (ex. prestations familiales).</li><li>La <strong>prévoyance</strong> : individuelle (épargne, assurance privée) ou collective (mutualisation des risques).</li></ul>"},{"i":"a90cca79b8f4","n":19,"o":"19-1","u":"Définition","t":"Protection sociale : connaître la définition et les principes de fonctionnement","q":"Quels sont les différents risques sociaux couverts par la protection sociale ?","a":"<p>Les risques sociaux sont les situations qui compromettent la sécurité financière d'un individu ou de sa famille par <stong>baisse des ressources</stong> ou <stong>hausse des dépenses</stong>. Ils incluent :</p><ul><li>La <strong>vieillesse</strong></li><li>La <strong>maladie</strong></li><li>Le <strong>chômage</strong></li><li>Les <strong>charges de famille</strong></li><li>Les accidents du travail (<strong>AT</strong>)</li></ul>"},{"i":"e3d9df8a4af3","n":19,"o":"19-1","u":"Définition","t":"Protection sociale : connaître la définition et les principes de fonctionnement","q":"Quelle est la définition de la protection sociale en France ?","a":"<p>La protection sociale désigne l'ensemble des mécanismes qu'une société accorde à ses membres pour faire face aux <strong>risques sociaux</strong> de l'existence et à leurs conséquences financières.</p>"},{"i":"1832a7bd4341","n":19,"o":"19-10","u":"Définition","t":"Connaître la définition du ticket modérateur, du forfait hospitalier, de la participation forfaitaire, de la franchise médicale, du tiers payant","q":"Décrivez la participation forfaitaire dans le système de santé français.","a":"<p>La <strong>participation forfaitaire</strong> est une somme de <strong>2 €</strong> déduite sur chaque consultation, analyse biologique ou acte de radiologie. Elle est plafonnée à <strong>50 € par an</strong> et ne peut <strong>pas être prise en charge par une complémentaire santé</strong>.</p>"},{"i":"b59365302da5","n":19,"o":"19-10","u":"Définition","t":"Connaître la définition du ticket modérateur, du forfait hospitalier, de la participation forfaitaire, de la franchise médicale, du tiers payant","q":"En quoi consiste la franchise médicale en France ?","a":"<p>La <strong>franchise médicale</strong> est une somme déduite des remboursements de l'Assurance maladie pour certains actes: <ul><li><strong>1 € par boîte de médicament</strong> ou par acte paramédical</li><li><strong>4 € par transport sanitaire</strong></li></ul>Elle est plafonnée à <strong>50 € par an</strong> et ne peut <strong>pas être prise en charge par une complémentaire santé</strong>.</p>"},{"i":"c3634a363382","n":19,"o":"19-10","u":"Définition","t":"Connaître la définition du ticket modérateur, du forfait hospitalier, de la participation forfaitaire, de la franchise médicale, du tiers payant","q":"Quelle est la définition du ticket modérateur en assurance maladie ?","a":"<p>Le <strong>ticket modérateur</strong> est la part des frais de santé qui reste à la charge de l'assuré après le remboursement de l'Assurance maladie. Il vise à responsabiliser financièrement le patient et à réguler la consommation de soins.</p>"},{"i":"d9d159659cd2","n":19,"o":"19-10","u":"Définition","t":"Connaître la définition du ticket modérateur, du forfait hospitalier, de la participation forfaitaire, de la franchise médicale, du tiers payant","q":"Qu'est-ce que le forfait hospitalier en France ?","a":"<p>Le <strong>forfait hospitalier</strong> est une somme forfaitaire due par le patient pour chaque jour d'hospitalisation (actuellement <strong>20 €/jour</strong>). Il couvre les frais d'hébergement et d'entretien. Il n'est <strong>pas pris en charge par l'Assurance maladie</strong> et peut être remboursé par une assurance complémentaire.</p>"},{"i":"da36060dd306","n":19,"o":"19-10","u":"Définition","t":"Connaître la définition du ticket modérateur, du forfait hospitalier, de la participation forfaitaire, de la franchise médicale, du tiers payant","q":"Qu'est-ce que le tiers payant en assurance maladie ?","a":"<p>Le <strong>tiers payant</strong> est un dispositif qui dispense le patient d'avancer la part des frais prise en charge par l'Assurance maladie. Le patient ne règle alors que le <strong>ticket modérateur</strong>, l'Assurance maladie payant directement le professionnel de santé.</p>"},{"i":"1fe12f94ffcb","n":19,"o":"19-11","u":"Définition","t":"Connaître le parcours de soins coordonnés","q":"Qu'est-ce que le parcours de soins coordonnés en France ?","a":"<p>Le parcours de soins coordonnés est un dispositif qui organise la prise en charge médicale du patient autour d'un <strong>médecin traitant (MT)</strong>. Ce dernier joue le rôle de pivot pour l'orientation et le suivi des soins du patient.</p>"},{"i":"822c09fc6aa2","n":19,"o":"19-11","u":"Définition","t":"Connaître le parcours de soins coordonnés","q":"Quelles sont les conséquences pour un patient de plus de 16 ans qui ne respecte pas le parcours de soins coordonnés ?","a":"<p>Un patient de <strong>plus de 16 ans</strong> qui consulte un spécialiste sans avoir été orienté par son médecin traitant subit une baisse du taux de remboursement. Le remboursement est alors <strong>abaissé à 30 %</strong> au lieu des 70 % habituels, et des <strong>dépassements d'honoraires</strong> peuvent être appliqués.</p>"},{"i":"a12254a010a0","n":19,"o":"19-11","u":"Définition","t":"Connaître le parcours de soins coordonnés","q":"Quel est le rôle principal du médecin traitant dans le parcours de soins coordonnés ?","a":"<ul><li>Il est le <strong>premier recours</strong> aux soins.</li><li>Il assure la <strong>coordination</strong> du suivi médical.</li><li>Il <strong>oriente</strong> le patient vers les spécialistes adaptés, avec l'accord du patient.</li><li>Il <strong>gère le dossier médical</strong> du patient.</li><li>Il établit le protocole de soins pour les <strong>ALD</strong> (Affections de Longue Durée) et assure la <strong>prévention</strong> personnalisée.</li></ul>"},{"i":"aab073b3e431","n":19,"o":"19-11","u":"Définition","t":"Connaître le parcours de soins coordonnés","q":"Quelles sont les situations permettant un accès direct à un professionnel de santé sans passer par le médecin traitant, tout en restant dans le parcours de soins coordonnés ?","a":"<ul><li>Les <strong>urgences</strong> (SAMU, SOS médecins).</li><li>Les consultations <strong>hors lieu de résidence</strong>.</li><li>Les consultations auprès d'un <strong>médecin remplaçant</strong>.</li><li>L'accès direct à certaines spécialités comme le <strong>gynécologue</strong>, l'<strong>ophtalmologue</strong>, le <strong>stomatologue</strong>.</li><li>Pour le <strong>psychiatre</strong>, l'accès direct est remboursé chez les patients de <strong>16-25 ans</strong> sans adressage préalable.</li></ul>"},{"i":"06a4819457e9","n":19,"o":"19-12","u":"Définition","t":"Connaître le protocole de soins affection de longue durée (ALD) avec exonération du ticket modérateur","q":"Quel est le rôle du protocole de soins ALD et qui l'établit ?","a":"<p>Le protocole de soins ALD est le document qui <strong>officialise</strong> la prise en charge à 100% pour l'ALD. Il est établi par le <strong>médecin traitant</strong>, en concertation avec les spécialistes, conformément aux recommandations de la HAS. Il reçoit l'avis du médecin-conseil de l'Assurance maladie. Un exemplaire est remis au patient qui le signe.</p>"},{"i":"5d980082b48a","n":19,"o":"19-12","u":"Définition","t":"Connaître le protocole de soins affection de longue durée (ALD) avec exonération du ticket modérateur","q":"Comment les prescriptions médicamenteuses sont-elles gérées dans le cadre d'une ALD exonérante ?","a":"<p>Les prescriptions sont réalisées via une <strong>ordonnance bizone</strong>. Cette ordonnance sépare les prescriptions en rapport avec l'ALD, qui sont <strong>exonérées</strong> à 100 %, de celles sans rapport avec l'ALD, pour lesquelles le <strong>ticket modérateur</strong> est appliqué.</p>"},{"i":"7952c186e442","n":19,"o":"19-12","u":"Définition","t":"Connaître le protocole de soins affection de longue durée (ALD) avec exonération du ticket modérateur","q":"Quelles sont les obligations d'un patient bénéficiant d'une ALD exonérante ?","a":"<ul><li>Présenter son <strong>volet du protocole</strong> à chaque professionnel consulté (sauf urgence).</li><li>Se conformer au <strong>projet thérapeutique</strong> défini par le médecin traitant.</li><li>Se présenter aux <strong>contrôles</strong> organisés par l'Assurance maladie.</li></ul>"},{"i":"97688f347d45","n":19,"o":"19-12","u":"Définition","t":"Connaître le protocole de soins affection de longue durée (ALD) avec exonération du ticket modérateur","q":"Dans quel contexte un patient est-il exonéré du ticket modérateur pour les soins liés à une Affection Longue Durée (ALD) ?","a":"<p>Un patient est exonéré du ticket modérateur pour les soins liés à une ALD lorsque cette affection comporte un <strong>traitement prolongé et coûteux</strong>, entraînant une prise en charge à <strong>100 %</strong> sur ces soins.</p>"},{"i":"a4752d63beeb","n":19,"o":"19-12","u":"Définition","t":"Connaître le protocole de soins affection de longue durée (ALD) avec exonération du ticket modérateur","q":"Quelles sont les trois portes d'entrée pour bénéficier d'une Affection de Longue Durée (ALD) exonérante ?","a":"<ul><li>Les <strong>30 affections de la liste</strong> (ALD 30) comme le diabète, les tumeurs malignes, ou la sclérose en plaques.</li><li>La <strong>31e maladie</strong> (hors liste) : une forme grave ou invalidante non listée, nécessitant un traitement prolongé de plus de 6 mois et une thérapeutique coûteuse.</li><li>La <strong>32e maladie</strong> : une polypathologie invalidante nécessitant des soins continus de plus de 6 mois.</li></ul>"},{"i":"1d14dc0d1230","n":19,"o":"19-2","u":"Définition","t":"Connaître la nature des prestations de protection sociale en France","q":"Quelles sont les deux natures principales des prestations sociales versées en France et leurs exemples respectifs ?","a":"<p>Les prestations sociales versées en France sont de deux natures :</p><ul><li>Les <strong>prestations en espèces</strong> : il s'agit d'un revenu de remplacement. Exemples : <strong>indemnités journalières</strong>, <strong>pensions de retraite</strong>.</li><li>Les <strong>prestations en nature</strong> : elles correspondent au remboursement de dépenses engagées (ex: remboursements de <strong>soins de santé</strong>) ou au financement direct de services sans avance de frais (ex: <strong>médicaments</strong>, <strong>tiers payant</strong>).</li></ul>"},{"i":"25ed3d2dd85c","n":19,"o":"19-2","u":"Définition","t":"Connaître la nature des prestations de protection sociale en France","q":"Comment la protection sociale en France agit-elle pour fournir ses prestations ?","a":"<p>La protection sociale en France agit par deux canaux principaux :</p><ul><li>L'accès à des <strong>services sociaux</strong> fournis gratuitement ou à prix réduit (ex: crèches, cantines).</li><li>Le versement de <strong>prestations sociales</strong> directement aux individus.</li></ul>"},{"i":"320220cc9007","n":19,"o":"19-2","u":"Définition","t":"Connaître la nature des prestations de protection sociale en France","q":"Quelles sont les six catégories de prestations sociales (avec leurs risques associés et parts contributives approximatives) en France ?","a":"<p>Les six catégories de prestations sociales, correspondant à six risques différents, sont :</p><ul><li><strong>Vieillesse-survie</strong> : environ <strong>45 %</strong> des prestations (ex: retraites, pensions de réversion).</li><li><strong>Santé</strong> : environ <strong>35 %</strong> des prestations (ex: remboursements de soins, indemnités journalières, rentes d'invalidité).</li><li><strong>Famille</strong> : environ <strong>8 %</strong> des prestations (ex: allocations familiales, bourses d'études).</li><li><strong>Emploi</strong> : environ <strong>6 %</strong> des prestations (ex: allocations chômage, formation professionnelle).</li><li><strong>Pauvreté-exclusion</strong> : environ <strong>3 %</strong> des prestations (ex: RSA).</li><li><strong>Logement</strong> : environ <strong>2 %</strong> des prestations (ex: APL).</li></ul><p>À noter que les risques <strong>vieillesse-survie</strong> et <strong>santé</strong> représentent à eux seuls environ <strong>80 %</strong> des prestations sociales versées.</p>"},{"i":"0b49deed4acb","n":19,"o":"19-5","u":"Définition","t":"Connaître le régime général de la sécurité sociale","q":"Quel est l'organisme en charge de la collecte des cotisations sociales pour le régime général de la Sécurité sociale ?","a":"<p>L'organisme en charge de la collecte des cotisations sociales (employeurs et indépendants) est l'<strong>URSSAF</strong>, qui constitue une branche à part entière du régime général.</p>"},{"i":"11c42efc348e","n":19,"o":"19-5","u":"Définition","t":"Connaître le régime général de la sécurité sociale","q":"Quelles sont les attributions de la branche Maladie du régime général de la Sécurité sociale, gérée par la CNAM ?","a":"<p>La branche Maladie, gérée par la CNAM, couvre :</p><ul><li>La <strong>maladie</strong></li><li>La <strong>maternité</strong></li><li>L'<strong>invalidité</strong></li><li>Le <strong>décès</strong></li><li>Elle intègre également les <strong>accidents du travail et les maladies professionnelles (AT/MP)</strong>.</li></ul>"},{"i":"122d0ae5d1c3","n":19,"o":"19-5","u":"Définition","t":"Connaître le régime général de la sécurité sociale","q":"Combien de branches autonomes composent le régime général de la Sécurité sociale, et sont-elles centralisées ou décentralisées ?","a":"<p>Le régime général est composé de <strong>4 branches autonomes</strong> (avec une 5ᵉ en construction). Chaque branche est pilotée par une <strong>Caisse nationale</strong> qui coordonne un réseau de <strong>caisses territoriales</strong>. Ces caisses territoriales sont des organismes de droit privé, avec une mission de service public, sous tutelle de l'État.</p>"},{"i":"1b66315e3777","n":19,"o":"19-5","u":"Définition","t":"Connaître le régime général de la sécurité sociale","q":"Quel est le pourcentage de la population couverte par le régime général de la Sécurité sociale en France ?","a":"<p>Le régime général de la Sécurité sociale couvre <strong>88 %</strong> de la population française.</p>"},{"i":"77cf9c33f25a","n":19,"o":"19-5","u":"Définition","t":"Connaître le régime général de la sécurité sociale","q":"Qui sont les principales catégories de personnes couvertes par le régime général de la Sécurité sociale en France ?","a":"<p>Les principales catégories de personnes couvertes sont :</p><ul><li>Les <strong>salariés</strong></li><li>Les <strong>étudiants</strong></li><li>Les <strong>simples résidents</strong></li><li>Depuis 2018, les <strong>indépendants</strong> (ex-RSI)</li></ul>"},{"i":"e60aed341141","n":19,"o":"19-5","u":"Définition","t":"Connaître le régime général de la sécurité sociale","q":"Quelles sont les quatre branches autonomes du régime général de la Sécurité sociale et leurs caisses nationales respectives ?","a":"<ul><li>La branche <strong>Maladie</strong>, gérée par la <strong>CNAM</strong> (Caisse Nationale d'Assurance Maladie).</li><li>La branche <strong>Famille</strong>, gérée par la <strong>CAF</strong> (Caisses d'Allocations Familiales).</li><li>La branche <strong>Vieillesse</strong>, gérée par la <strong>CNAV</strong> (Caisse Nationale d'Assurance Vieillesse, ou Assurance Retraite).</li><li>La branche <strong>Recouvrement</strong>, gérée par l'<strong>URSSAF</strong> (Unions de Recouvrement des cotisations de Sécurité Sociale et d'Allocations Familiales).</li></ul>"},{"i":"f8acb0a3f2d7","n":19,"o":"19-5","u":"Définition","t":"Connaître le régime général de la sécurité sociale","q":"La gestion du chômage fait-elle partie du régime général de la Sécurité sociale en France ?","a":"<p>Non, la gestion du <strong>chômage</strong> ne fait pas partie du régime général ni même de la Sécurité sociale. Elle est gérée de façon indépendante, notamment par <strong>France Travail</strong> (anciennement Pôle emploi).</p>"},{"i":"36294d83570a","n":19,"o":"19-8","u":"Définition","t":"Connaître les différents régimes de sécurité sociale","q":"Comment les assurés sont-ils regroupés au sein de la Sécurité sociale française ?","a":"<p>Les assurés sont regroupés en différents régimes, principalement selon leur <strong>activité professionnelle</strong>.</p>"},{"i":"5c9b81392486","n":19,"o":"19-8","u":"Définition","t":"Connaître les différents régimes de sécurité sociale","q":"Quel est le statut actuel de la protection sociale des indépendants (ancien RSI) en France ?","a":"<p>Depuis <strong>2018</strong>, la protection sociale des indépendants (ancien RSI) est confiée au <strong>régime général</strong> de la Sécurité sociale.</p>"},{"i":"ff1c90bd2566","n":19,"o":"19-8","u":"Définition","t":"Connaître les différents régimes de sécurité sociale","q":"Quels sont les trois principaux types de régimes de sécurité sociale en France et qui couvrent-ils ?","a":"<ul><li>Le <strong>régime général</strong> : il couvre environ <strong>88 %</strong> de la population, incluant les salariés, les étudiants, les simples résidents, et depuis 2018, les indépendants (anciens du RSI).</li><li>Le <strong>régime agricole (MSA)</strong> : il couvre environ <strong>5 %</strong> de la population, composé des exploitants et salariés agricoles.</li><li>Les <strong>régimes spéciaux</strong> : ils représentent un ensemble de régimes historiques (ex : fonction publique, SNCF, RATP, EDF-GDF), dont la plupart ont refusé l'intégration au régime général en 1945. Seuls 11 d'entre eux recensent plus de 20 000 cotisants.</li></ul>"},{"i":"17b042d843a3","n":19,"o":"19-9","u":"Définition","t":"Connaître les missions de l’assurance maladie du régime général de la sécurité sociale","q":"Quels risques principaux sont gérés par l'Assurance Maladie (CNAM) au sein du régime général ?","a":"<ul><li>Le risque <strong>maladie</strong></li><li>Le risque <strong>maternité</strong></li><li>Le risque <strong>invalidité-décès</strong></li><li>Les risques <strong>AT/MP</strong> (accidents du travail et maladies professionnelles)</li></ul>"},{"i":"3ea02a338e11","n":19,"o":"19-9","u":"Définition","t":"Connaître les missions de l’assurance maladie du régime général de la sécurité sociale","q":"Quel rôle joue l'UNCAM concernant la tarification et le remboursement des prestations de santé ?","a":"<p>L'UNCAM (Union Nationale des Caisses d'Assurance Maladie), qui inclut le régime général et la MSA, est chargée de fixer le <strong>taux de prise en charge</strong> (PEC) et le <strong>champ des prestations remboursables</strong>. Elle intervient également dans la <strong>tarification des actes</strong> via le codage par la CCAM et la NGAP, et le système T2A pour les établissements.</p>"},{"i":"489bd0d5e36f","n":19,"o":"19-9","u":"Définition","t":"Connaître les missions de l’assurance maladie du régime général de la sécurité sociale","q":"Comment l'Assurance Maladie contribue-t-elle à la maîtrise des dépenses de santé (gestion du risque) ?","a":"<ul><li>Par la <strong>maîtrise médicalisée des dépenses</strong>, visant à l'efficience qualité/coût.</li><li>Par sa participation au <strong>CEPS</strong> (Comité Économique des Produits de Santé), qui fixe le prix des médicaments.</li><li>Par la <strong>planification de l'offre de soins</strong> en collaboration avec les ARS.</li></ul>"},{"i":"555dfbaea025","n":19,"o":"19-9","u":"Définition","t":"Connaître les missions de l’assurance maladie du régime général de la sécurité sociale","q":"À quoi correspond la Protection universelle maladie (PUMa) et qui est couverte ?","a":"<p>La PUMa (Protection universelle maladie) a remplacé la CMU de base. Elle garantit la <strong>couverture des frais de santé à toute personne qui travaille ou réside en France de façon stable et régulière</strong>, et ce, <strong>sans condition de ressources</strong>. Seuls les mineurs de moins de 18 ans conservent le statut d'ayant-droit.</p>"},{"i":"5ef779fd4ae1","n":19,"o":"19-9","u":"Définition","t":"Connaître les missions de l’assurance maladie du régime général de la sécurité sociale","q":"Quelle est la mission centrale de l'Assurance Maladie du régime général ?","a":"<p>La mission centrale de l'Assurance Maladie du régime général est la <strong>prise en charge des soins</strong> dispensés aux assurés sociaux.</p>"},{"i":"aa031cca4f70","n":19,"o":"19-9","u":"Définition","t":"Connaître les missions de l’assurance maladie du régime général de la sécurité sociale","q":"Quels sont les trois objectifs secondaires de l'Assurance Maladie du régime général, en plus de sa mission centrale ?","a":"<ul><li>L'<strong>amélioration de la santé</strong> de la population</li><li>L'<strong>efficience du système de soins</strong></li><li>La <strong>maîtrise des dépenses de santé</strong></li></ul>"},{"i":"ab2d476e00e4","n":19,"o":"19-9","u":"Définition","t":"Connaître les missions de l’assurance maladie du régime général de la sécurité sociale","q":"Quelles actions l'Assurance Maladie mène-t-elle en matière de prévention et d'information des assurés ?","a":"<ul><li>La <strong>prévention</strong> (ex: lutte contre le tabac, vaccination).</li><li>Le <strong>dépistage organisé des cancers</strong>.</li><li>L'<strong>information des assurés</strong>.</li><li>La <strong>lutte contre la fraude</strong> (par des méthodes comme le datamining et le big data).</li></ul>"},{"i":"fc2c07daca80","n":19,"o":"19-9","u":"Définition","t":"Connaître les missions de l’assurance maladie du régime général de la sécurité sociale","q":"Quel est le rôle du service du contrôle médical de l'Assurance Maladie ?","a":"<p>Le service du contrôle médical, composé de <strong>médecins-conseils</strong>, a pour rôle de <strong>vérifier la pertinence des soins</strong>. Il peut également déclencher des sanctions contre les professionnels et assurés en cas d'abus ou de fraudes.</p>"}]};